import{O as t}from"./index-BaR--PIO.js";const p={list(){return t.get("/pipelines")},overview(){return t.get("/overview")},allBuilds(){return t.get("/builds")},get(e){return t.get(`/pipelines/${e}`)},create(e){return t.post("/pipelines",e)},update(e,i){return t.put(`/pipelines/${e}`,i)},remove(e){return t.del(`/pipelines/${e}`)},build(e){return t.post(`/pipelines/${e}/build`)},rename(e,i){return t.post(`/pipelines/${e}/rename`,{name:i})},notifyContacts(){return t.get("/notify/contacts")},testNotify(e){return t.post(`/pipelines/${e}/notify/test`)}};export{p};
